function Home() {
  const featured = products.slice(0, 4);
  return <Shell><section className="paper-grain overflow-hidden bg-[#FCE0E0]"><div className="container-lunaria grid min-h-[570px] items-center gap-10 py-16 md:grid-cols-[1.03fr_.97fr] md:py-20"><div className="animate-rise"><p className="mb-5 flex items-center gap-2 text-xs font-bold uppercase tracking-[.2em] text-[#8B659C]"><span className="h-px w-8 bg-[#B274A2]" />A little shop for big imaginations</p><h1 className="max-w-[580px] font-display text-[clamp(3.6rem,8vw,7.7rem)] leading-[.88] tracking-[-.065em] text-[#30263B]">Find your next <em className="text-[#48458F]">favourite</em> thing.</h1><p className="mt-7 max-w-[430px] text-base leading-7 text-[#5e5262]">Independent books, thoughtful paper goods, and gifts chosen in Algiers for people who still like to wander through a shop.</p><div className="mt-8 flex flex-wrap gap-3"><Link href="/shop" className="inline-flex items-center gap-3 bg-[#48458F] px-6 py-3.5 text-sm font-bold text-white transition hover:bg-[#30263B]" data-testid="link-hero-shop">Browse the shelves <ArrowRight size={16} /></Link><Link href="/about" className="inline-flex items-center gap-2 border border-[#8B659C] px-6 py-3.5 text-sm font-bold text-[#48458F] hover:bg-[#FFF9F7]/60" data-testid="link-hero-story">Our story</Link></div></div><div className="relative mx-auto h-[390px] w-full max-w-[470px] animate-rise md:h-[450px]" style={{ animationDelay: '.12s' }}><div className="absolute left-[10%] top-[7%] h-[77%] w-[55%] rotate-[-8deg] bg-[#48458F] p-7 text-[#FFF9F7] shadow-2xl"><span className="text-[10px] font-bold tracking-[.25em]">NABI BOOKS</span><div className="mt-20 font-display text-4xl leading-[.9]">Stories<br /><em>worth<br />keeping.</em></div><div className="absolute bottom-6 text-xs text-[#F8B2B2]">BOOKS · PAPER · WONDER</div></div><div className="absolute bottom-[1%] right-[6%] h-[75%] w-[47%] rotate-[9deg] bg-[#FFF9F7] p-6 shadow-xl"><span className="text-[10px] font-bold tracking-[.25em] text-[#B274A2]">A SMALL NOTE</span><div className="mt-16 font-display text-4xl leading-[.9] text-[#30263B]">Take<br /><em>your<br />time.</em></div><div className="absolute bottom-7 left-6 h-2 w-24 bg-[#F8B2B2]" /></div><div className="animate-float absolute right-[9%] top-[9%] grid h-16 w-16 place-items-center rounded-full border border-[#48458F] bg-[#F8B2B2] text-center font-display text-lg leading-4 text-[#48458F]">read<br />slowly</div></div></div></section>
    <section className="container-lunaria py-20 md:py-28"><SectionHeading eyebrow="From the front table" title="New things, good company." description="A rotating edit of books and paper goods that have earned their place in our front window." href="/shop" linkLabel="See everything" /><div className="grid grid-cols-2 gap-x-4 gap-y-10 md:grid-cols-4 md:gap-6">{featured.map((product, index) => <ProductCard key={product.id} product={product} index={index} />)}</div></section>
    <section className="bg-[#E8D7F0] py-20"><div className="container-lunaria grid items-center gap-10 md:grid-cols-[.9fr_1.1fr]"><div><p className="text-xs font-bold uppercase tracking-[.2em] text-[#8B659C]">The reading room</p><h2 className="mt-3 max-w-md font-display text-4xl leading-tight text-[#30263B] md:text-5xl">A good book changes the shape of an afternoon.</h2><p className="mt-5 max-w-md text-sm leading-7 text-[#5e5262]">Our booksellers read widely and recommend honestly. Start with a mood, a question, or simply the color you want to see on your bedside table.</p><Link href="/books" className="mt-7 inline-flex items-center gap-2 text-sm font-bold text-[#48458F]" data-testid="link-reading-room">Enter the reading room <ArrowRight size={16} /></Link></div><div className="grid grid-cols-2 gap-3 sm:grid-cols-4">{['I need a fresh start', 'For a rainy Sunday', 'A gift for a maker', 'Something to underline'].map((text, index) => <Link key={text} href={index === 2 ? '/stationery' : '/books'} className={`flex min-h-[148px] items-end p-4 text-sm font-semibold leading-5 ${index % 2 === 0 ? 'bg-[#FFF9F7]' : 'bg-[#F8B2B2]'} text-[#30263B] transition hover:-translate-y-1`} data-testid={`link-mood-${index}`}><span>{text}<br /><span className="mt-2 inline-block text-xs font-normal text-[#746875]">Explore →</span></span></Link>)}</div></div></section>
    <section className="container-lunaria py-20 md:py-28"><div className="grid items-center gap-8 border-y border-[#eadbd9] py-10 md:grid-cols-[1fr_2fr]"><div><p className="text-xs font-bold uppercase tracking-[.2em] text-[#B274A2]">A note from the counter</p><p className="mt-3 font-display text-3xl leading-tight text-[#30263B]">“The nicest shops leave a little room for surprise.”</p></div><div className="flex flex-wrap items-center justify-between gap-6"><div className="flex -space-x-2">{['MV', 'EP', 'NS', 'IB'].map((initials) => <span key={initials} className="grid h-10 w-10 place-items-center rounded-full border-2 border-[#FFF9F7] bg-[#B274A2] text-xs font-bold text-white">{initials}</span>)}</div><p className="max-w-xs text-sm leading-6 text-[#746875]">Join 2,400 curious readers getting our monthly list of books we cannot stop talking about.</p><Link href="/contact" className="text-sm font-bold text-[#48458F] underline decoration-[#F8B2B2] decoration-2 underline-offset-4" data-testid="link-home-contact">Come say hello</Link></div></div></section>
  </Shell>;
}

function Catalog({ kind, title, eyebrow, description }: { kind?: ProductKind; title: string; eyebrow: string; description: string }) {
  const [sort, setSort] = useState('featured');
  const [filter, setFilter] = useState('all');
  const [showFilters, setShowFilters] = useState(false);
  const filtered = useMemo(() => products.filter((product) => !kind || product.kind === kind).filter((product) => filter === 'all' || product.availability === 'Only 3 left' || product.availability === 'Only 5 left').sort((a, b) => sort === 'low' ? a.price - b.price : sort === 'high' ? b.price - a.price : sort === 'rating' ? b.rating - a.rating : products.indexOf(a) - products.indexOf(b)), [kind, sort, filter]);
  return <Shell><div className="bg-[#FFF1EC]"><div className="container-lunaria py-14 md:py-20"><p className="text-xs font-bold uppercase tracking-[.2em] text-[#B274A2]">{eyebrow}</p><h1 className="mt-3 font-display text-5xl tracking-[-.04em] text-[#30263B] md:text-7xl">{title}</h1><p className="mt-4 max-w-xl text-base leading-7 text-[#746875]">{description}</p></div></div><section className="container-lunaria py-10 md:py-14"><div className="mb-8 flex flex-wrap items-center justify-between gap-4 border-b border-[#eadbd9] pb-5"><p className="text-sm text-[#746875]"><strong className="text-[#30263B]">{filtered.length}</strong> thoughtfully chosen pieces</p><div className="flex gap-2"><button onClick={() => setShowFilters(!showFilters)} className="flex items-center gap-2 border border-[#e6d4d7] px-3 py-2 text-xs font-bold uppercase tracking-[.1em] text-[#48458F] md:hidden" data-testid="button-toggle-filters"><SlidersHorizontal size={15} />Filter</button><label className="flex items-center gap-2 text-xs font-bold uppercase tracking-[.1em] text-[#746875]">Sort<select value={sort} onChange={(event) => setSort(event.target.value)} className="bg-transparent text-[#48458F] outline-none" aria-label="Sort products" data-testid="select-sort"><option value="featured">Featured</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option><option value="rating">Highest rated</option></select><ChevronDown size={14} /></label></div></div>{showFilters && <div className="mb-7 flex gap-2 border-b border-[#eadbd9] pb-6 md:hidden"><button onClick={() => setFilter('all')} className={`border px-3 py-2 text-xs ${filter === 'all' ? 'border-[#48458F] bg-[#48458F] text-white' : 'border-[#e6d4d7]'}`} data-testid="button-filter-all">All</button><button onClick={() => setFilter('limited')} className={`border px-3 py-2 text-xs ${filter === 'limited' ? 'border-[#48458F] bg-[#48458F] text-white' : 'border-[#e6d4d7]'}`} data-testid="button-filter-limited">Limited stock</button></div>}<div className="grid grid-cols-2 gap-x-4 gap-y-12 md:grid-cols-3 md:gap-x-7 lg:grid-cols-4">{filtered.map((product, index) => <ProductCard key={product.id} product={product} index={index} />)}</div>{filtered.length === 0 && <EmptyState title="Nothing on this shelf yet" message="Try widening your filters and see where the browsing takes you." href="/shop" label="Back to all shelves" />}</section></Shell>;
}

function ProductPage() {
  const { id = '' } = useParams<{ id: string }>();
  const product = findProduct(id);
  const { wishlist, toggleWishlist, addToCart } = useStore();
  const [quantity, setQuantity] = useState(1);
  const [variant, setVariant] = useState(product?.colors[0] || 'Default');
  if (!product) return <Shell><EmptyState title="That title has wandered off" message="We could not find the item you were looking for." href="/shop" label="Return to the shelves" /></Shell>;
  return <Shell><div className="container-lunaria py-8 md:py-14"><Link href={product.kind === 'book' ? '/books' : '/stationery'} className="mb-8 inline-flex items-center gap-2 text-xs font-bold uppercase tracking-[.13em] text-[#746875]" data-testid="link-product-back"><ArrowLeft size={15} />Back to {product.kind === 'book' ? 'books' : 'stationery'}</Link><div className="grid gap-10 md:grid-cols-[.9fr_1.1fr] md:gap-16"><div><ProductImage product={product} large /></div><div className="flex flex-col justify-center"><p className="text-xs font-bold uppercase tracking-[.2em] text-[#B274A2]">{product.kind === 'book' ? 'A book to keep close' : product.type}</p><h1 className="mt-3 font-display text-5xl leading-[.98] tracking-[-.04em] text-[#30263B] md:text-6xl">{product.title}</h1><p className="mt-3 font-display text-xl italic text-[#8B659C]">{product.author || 'A NABI BOOKS paper good'}</p><div className="mt-5 flex items-center gap-4"><span className="flex items-center gap-1 text-sm text-[#746875]"><Star size={15} fill="#B274A2" className="text-[#B274A2]" /> {product.rating} · 18 reader notes</span><span className="text-sm text-[#B274A2]">{product.availability}</span></div><p className="mt-7 max-w-lg text-base leading-7 text-[#5e5262]">{product.description}</p><p className="mt-7 border-t border-[#eadbd9] pt-5 text-2xl font-semibold text-[#48458F]">{money(product.price)}</p><div className="mt-6 flex flex-wrap gap-3">{product.colors.map((color) => <button key={color} onClick={() => setVariant(color)} className={`border px-4 py-2 text-sm ${variant === color ? 'border-[#48458F] bg-[#48458F] text-white' : 'border-[#e6d4d7] text-[#5e5262] hover:border-[#48458F]'}`} data-testid={`button-variant-${color.toLowerCase()}`}>{color}</button>)}</div><div className="mt-7 flex flex-wrap gap-3"><div className="flex items-center border border-[#d9c5cb]"><button onClick={() => setQuantity(Math.max(1, quantity - 1))} className="grid h-12 w-11 place-items-center text-[#48458F] hover:bg-[#FCE0E0]" aria-label="Decrease quantity" data-testid="button-quantity-decrease"><Minus size={15} /></button><span className="w-9 text-center text-sm" data-testid="text-product-quantity">{quantity}</span><button onClick={() => setQuantity(quantity + 1)} className="grid h-12 w-11 place-items-center text-[#48458F] hover:bg-[#FCE0E0]" aria-label="Increase quantity" data-testid="button-quantity-increase"><Plus size={15} /></button></div><button onClick={() => addToCart(product.id, quantity, variant)} className="flex h-12 flex-1 items-center justify-center gap-2 bg-[#48458F] px-7 text-sm font-bold text-white transition hover:bg-[#30263B] sm:flex-none" data-testid="button-product-add">Add to bag <ShoppingBag size={16} /></button><button onClick={() => toggleWishlist(product.id)} className={`grid h-12 w-12 place-items-center border ${wishlist.includes(product.id) ? 'border-[#B274A2] text-[#B274A2]' : 'border-[#d9c5cb] text-[#48458F]'} hover:bg-[#FCE0E0]`} aria-label="Toggle wishlist" data-testid="button-product-wishlist"><Heart size={18} fill={wishlist.includes(product.id) ? 'currentColor' : 'none'} /></button></div><div className="mt-8 grid gap-3 border-t border-[#eadbd9] pt-6 text-sm text-[#746875] sm:grid-cols-2"><p className="flex gap-2"><Package size={17} className="shrink-0 text-[#B274A2]" /> Carefully packed in recyclable materials</p><p className="flex gap-2"><BookOpen size={17} className="shrink-0 text-[#B274A2]" /> {product.details}</p></div></div></div></div></Shell>;
}

function EmptyState({ title, message, href, label }: { title: string; message: string; href: string; label: string }) {
  return <div className="container-lunaria flex min-h-[430px] flex-col items-center justify-center py-20 text-center"><div className="grid h-16 w-16 place-items-center rounded-full bg-[#E8D7F0] text-[#48458F]"><BookOpen size={25} /></div><h1 className="mt-6 font-display text-4xl text-[#30263B]">{title}</h1><p className="mt-3 max-w-sm text-sm leading-6 text-[#746875]">{message}</p><Link href={href} className="mt-7 bg-[#48458F] px-6 py-3 text-sm font-bold text-white" data-testid="link-empty-action">{label}</Link></div>;
}

function CartPage() {
  const { cart, cartTotal, updateQuantity, removeFromCart } = useStore();
  const shipping = cartTotal >= 6000 || cartTotal === 0 ? 0 : 600;
  if (cart.length === 0) return <Shell><EmptyState title="Your bag is waiting" message="A good browsing session should end with at least one maybe. Take another turn around the shelves." href="/shop" label="Keep browsing" /></Shell>;
  return <Shell><div className="container-lunaria py-14 md:py-20"><p className="text-xs font-bold uppercase tracking-[.2em] text-[#B274A2]">Your little stack</p><h1 className="mt-3 font-display text-5xl text-[#30263B] md:text-6xl">Your bag</h1><div className="mt-10 grid gap-10 lg:grid-cols-[1fr_360px]"><div className="divide-y divide-[#eadbd9] border-y border-[#eadbd9]">{cart.map((item) => { const product = findProduct(item.id); if (!product) return null; return <div key={item.id} className="flex gap-4 py-6 sm:gap-6" data-testid={`row-cart-${item.id}`}><div className="w-24 shrink-0 sm:w-32"><ProductImage product={product} /></div><div className="flex min-w-0 flex-1 flex-col justify-between gap-4 sm:flex-row"><div><Link href={`/product/${product.id}`} className="font-display text-xl text-[#30263B] hover:text-[#48458F]" data-testid={`link-cart-product-${product.id}`}>{product.title}</Link><p className="mt-1 text-sm text-[#746875]">{product.author || product.type}</p><button onClick={() => removeFromCart(item.id)} className="mt-4 flex items-center gap-1 text-xs font-bold uppercase tracking-[.1em] text-[#B274A2] hover:text-[#48458F]" data-testid={`button-remove-${product.id}`}><Trash2 size={13} />Remove</button></div><div className="flex items-center justify-between gap-8 sm:flex-col sm:items-end"><p className="font-semibold text-[#48458F]">{money(product.price * item.quantity)}</p><div className="flex items-center border border-[#d9c5cb]"><button onClick={() => updateQuantity(item.id, item.quantity - 1)} className="grid h-8 w-8 place-items-center text-[#48458F]" aria-label="Decrease quantity" data-testid={`button-cart-minus-${product.id}`}><Minus size={14} /></button><span className="w-8 text-center text-sm">{item.quantity}</span><button onClick={() => updateQuantity(item.id, item.quantity + 1)} className="grid h-8 w-8 place-items-center text-[#48458F]" aria-label="Increase quantity" data-testid={`button-cart-plus-${product.id}`}><Plus size={14} /></button></div></div></div></div>; })}</div><aside className="h-fit bg-[#FFF1EC] p-6 md:p-7"><h2 className="font-display text-2xl text-[#30263B]">A few numbers</h2><div className="mt-6 space-y-4 text-sm text-[#746875]"><div className="flex justify-between"><span>Subtotal</span><span className="font-semibold text-[#30263B]">{money(cartTotal)}</span></div><div className="flex justify-between"><span>Shipping</span><span className="font-semibold text-[#30263B]">{shipping ? money(shipping) : 'Free'}</span></div><div className="border-t border-[#e2cfd0] pt-4 text-base font-bold text-[#30263B] flex justify-between"><span>Total</span><span>{money(cartTotal + shipping)}</span></div></div><button onClick={() => alert('Checkout is simulated for this prototype.')} className="mt-7 flex w-full items-center justify-center gap-2 bg-[#48458F] py-3.5 text-sm font-bold text-white hover:bg-[#30263B]" data-testid="button-checkout">Continue to checkout <ArrowRight size={16} /></button><p className="mt-4 text-center text-xs leading-5 text-[#746875]">Free shipping on orders over 6,000 DA. No account needed.</p></aside></div></div></Shell>;
}

function WishlistPage() {
  const { wishlist, moveToCart, toggleWishlist } = useStore();
  const saved = products.filter((product) => wishlist.includes(product.id));
  return <Shell><div className="container-lunaria py-14 md:py-20"><p className="text-xs font-bold uppercase tracking-[.2em] text-[#B274A2]">Things worth keeping</p><h1 className="mt-3 font-display text-5xl text-[#30263B] md:text-6xl">Your wishlist</h1>{saved.length === 0 ? <EmptyState title="Save a little magic" message="Tap the heart on anything that catches your eye and it will wait here for you." href="/shop" label="Browse the shelves" /> : <><p className="mt-4 text-sm text-[#746875]">{saved.length} saved {saved.length === 1 ? 'piece' : 'pieces'}</p><div className="mt-10 grid grid-cols-2 gap-x-4 gap-y-12 md:grid-cols-3 md:gap-7 lg:grid-cols-4">{saved.map((product, index) => <div key={product.id} className="relative"><ProductCard product={product} index={index} /><div className="mt-3 flex gap-2"><button onClick={() => moveToCart(product.id)} className="flex-1 border border-[#48458F] py-2 text-xs font-bold uppercase tracking-[.1em] text-[#48458F] hover:bg-[#48458F] hover:text-white" data-testid={`button-move-cart-${product.id}`}>Move to bag</button><button onClick={() => toggleWishlist(product.id)} className="grid w-10 place-items-center border border-[#e6d4d7] text-[#B274A2]" aria-label={`Remove ${product.title}`} data-testid={`button-remove-wishlist-${product.id}`}><X size={16} /></button></div></div>)}</div></>}</div></Shell>;
}

function SearchPage() {
  const [location, setLocation] = useLocation();
  const query = new URLSearchParams(location.split('?')[1] || '').get('q') || '';
  const [value, setValue] = useState(query);
  const results = products.filter((product) => `${product.title} ${product.author || ''} ${product.type || ''}`.toLowerCase().includes(query.toLowerCase())).slice(0, 8);
  const submit = (event: FormEvent) => { event.preventDefault(); setLocation(`/search?q=${encodeURIComponent(value)}`); };
  return <Shell><div className="container-lunaria py-14 md:py-20"><p className="text-xs font-bold uppercase tracking-[.2em] text-[#B274A2]">Take a look around</p><h1 className="mt-3 font-display text-5xl text-[#30263B] md:text-6xl">Search the shelves</h1><form onSubmit={submit} className="mt-8 flex max-w-2xl items-center border-b-2 border-[#48458F] py-3"><Search size={20} className="mr-3 text-[#B274A2]" /><input autoFocus value={value} onChange={(event) => setValue(event.target.value)} className="min-w-0 flex-1 bg-transparent text-lg outline-none placeholder:text-[#b2a4ab]" placeholder="Try “poetry”, “journal”, or an author" aria-label="Search catalog" data-testid="input-search-page" /><button className="text-sm font-bold text-[#48458F]" data-testid="button-search-submit">Search</button></form>{query && <p className="mt-10 text-sm text-[#746875]">Showing {results.length} results for <strong className="text-[#30263B]">“{query}”</strong></p>}{query && results.length > 0 && <div className="mt-8 grid grid-cols-2 gap-x-4 gap-y-12 md:grid-cols-3 md:gap-7 lg:grid-cols-4">{results.map((product, index) => <ProductCard key={product.id} product={product} index={index} />)}</div>}{query && results.length === 0 && <EmptyState title="No exact match" message="Try a shorter phrase, or browse the shelves by mood instead." href="/shop" label="See all products" />}</div></Shell>;
}

function About() {
  return <Shell><section className="bg-[#E8D7F0]"><div className="container-lunaria grid min-h-[460px] items-center gap-10 py-16 md:grid-cols-[1fr_.8fr] md:py-24"><div><p className="text-xs font-bold uppercase tracking-[.2em] text-[#B274A2]">The story of NABI BOOKS</p><h1 className="mt-4 max-w-xl font-display text-6xl leading-[.92] tracking-[-.05em] text-[#30263B] md:text-8xl">A shop with its pages open.</h1></div><div className="border-l-2 border-[#B274A2] pl-6 text-base leading-8 text-[#5e5262]"><p>NABI BOOKS is a placeholder for an independent Algerian bookstore where browsing feels like a form of luck — the right sentence overheard, the right notebook at the right moment.</p><p className="mt-5">Thoughtfully chosen in Algiers, with a little bit of curiosity about what you might love next.</p></div></div></section><section className="container-lunaria grid gap-12 py-20 md:grid-cols-[1.1fr_.9fr] md:py-28"><div><p className="text-xs font-bold uppercase tracking-[.2em] text-[#B274A2]">What we believe</p><div className="mt-8 space-y-9">{[['01', 'Choose the unexpected', 'Our shelves make room for new voices, odd little treasures, and books that stay with you longer than expected.'], ['02', 'Paper is a place', 'A notebook is not just a container. It is an invitation to slow down and make a thought visible.'], ['03', 'Keep it human', 'We would rather make one honest recommendation than shout about everything at once.']].map(([number, title, copy]) => <div key={number} className="grid grid-cols-[42px_1fr] gap-5 border-t border-[#eadbd9] pt-5"><span className="font-mono text-sm text-[#B274A2]">{number}</span><div><h2 className="font-display text-2xl text-[#30263B]">{title}</h2><p className="mt-2 max-w-md text-sm leading-6 text-[#746875]">{copy}</p></div></div>)}</div></div><div className="relative min-h-[390px] bg-[#F8B2B2] p-8"><div className="absolute inset-7 border border-[#8B659C]" /><div className="relative flex h-full flex-col justify-between"><span className="text-xs font-bold uppercase tracking-[.18em] text-[#48458F]">Algiers · Algeria</span><p className="max-w-[250px] font-display text-4xl leading-tight text-[#30263B]">Come in for one thing.<br /><em>Leave with a story.</em></p><div className="flex justify-between text-xs font-bold uppercase tracking-[.15em] text-[#48458F]"><span>Books</span><span>Paper</span><span>Gifts</span></div></div></div></section><section className="bg-[#FFF1EC] py-16"><div className="container-lunaria flex flex-col items-center text-center"><p className="font-display text-3xl text-[#30263B]">“A bright spot for anyone who likes their errands a little dreamy.”</p><p className="mt-4 text-xs font-bold uppercase tracking-[.15em] text-[#B274A2]">— A sample note from NABI BOOKS</p></div></section></Shell>;
}

function Contact() {
  const [sent, setSent] = useState(false);
  const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); setSent(true); };
  return <Shell><div className="container-lunaria grid gap-12 py-14 md:grid-cols-[.8fr_1.2fr] md:py-24"><div><p className="text-xs font-bold uppercase tracking-[.2em] text-[#B274A2]">Come say hello</p><h1 className="mt-4 font-display text-6xl leading-[.92] text-[#30263B]">We'd love to hear from you.</h1><p className="mt-6 max-w-sm text-sm leading-7 text-[#746875]">A recommendation request, a question about an order, or a story about a book that found you at the right time.</p><div className="mt-10 space-y-5 text-sm text-[#5e5262]"><p className="flex gap-3"><MapPin size={19} className="text-[#B274A2]" />Algiers, Algeria<br />DZ · 16000</p><p className="flex gap-3"><Clock3 size={19} className="text-[#B274A2]" />Saturday–Thursday, 10am–6pm<br />Friday · closed</p><p className="flex gap-3"><Mail size={19} className="text-[#B274A2]" />hello@nabibooks.dz</p></div></div><div className="bg-[#FFF1EC] p-6 md:p-10">{sent ? <div className="flex min-h-[440px] flex-col items-center justify-center text-center"><div className="grid h-16 w-16 place-items-center rounded-full bg-[#E8D7F0] text-[#48458F]"><Check size={28} /></div><h2 className="mt-6 font-display text-4xl text-[#30263B]">Message received.</h2><p className="mt-3 max-w-sm text-sm leading-6 text-[#746875]">We will write back soon — usually within one or two open-shop days.</p><button onClick={() => setSent(false)} className="mt-7 text-sm font-bold text-[#48458F] underline decoration-[#F8B2B2] decoration-2 underline-offset-4" data-testid="button-send-another">Send another note</button></div> : <form onSubmit={submit} className="space-y-6"><div className="grid gap-6 sm:grid-cols-2"><label className="text-xs font-bold uppercase tracking-[.1em] text-[#746875]">Name<input required className="mt-2 w-full border-b border-[#d9c5cb] bg-transparent py-3 text-sm outline-none focus:border-[#48458F]" placeholder="Your name" data-testid="input-contact-name" /></label><label className="text-xs font-bold uppercase tracking-[.1em] text-[#746875]">Email<input required type="email" className="mt-2 w-full border-b border-[#d9c5cb] bg-transparent py-3 text-sm outline-none focus:border-[#48458F]" placeholder="you@example.com" data-testid="input-contact-email" /></label></div><label className="block text-xs font-bold uppercase tracking-[.1em] text-[#746875]">What can we help with?<select className="mt-2 w-full border-b border-[#d9c5cb] bg-transparent py-3 text-sm outline-none focus:border-[#48458F]" data-testid="select-contact-topic"><option>Book recommendation</option><option>Order question</option><option>Shop visit</option><option>Something else</option></select></label><label className="block text-xs font-bold uppercase tracking-[.1em] text-[#746875]">Your note<textarea required rows={6} className="mt-2 w-full resize-none border-b border-[#d9c5cb] bg-transparent py-3 text-sm outline-none focus:border-[#48458F]" placeholder="Tell us a little..." data-testid="textarea-contact-message" /></label><button type="submit" className="flex items-center gap-2 bg-[#48458F] px-7 py-3.5 text-sm font-bold text-white hover:bg-[#30263B]" data-testid="button-contact-submit">Send your note <Send size={16} /></button></form>}</div></div></Shell>;
}

function Router() {
  return <Switch><Route path="/" component={Home} /><Route path="/shop"><Catalog title="All the good things" eyebrow="The whole shop" description="A considered mix of books, notebooks, desk companions, and small gifts for curious people." /></Route><Route path="/books"><Catalog kind="book" title="Books to get lost in" eyebrow="The reading room" description="New fiction, thoughtful nonfiction, and poetry with a little weather in it." /></Route><Route path="/stationery"><Catalog kind="stationery" title="Paper for your ideas" eyebrow="The writing desk" description="Notebooks, pencils, and beautiful bits of paper for making a day feel more yours." /></Route><Route path="/product/:id" component={ProductPage} /><Route path="/about" component={About} /><Route path="/contact" component={Contact} /><Route path="/cart" component={CartPage} /><Route path="/wishlist" component={WishlistPage} /><Route path="/search" component={SearchPage} /><Route component={NotFound} /></Switch>;
}

function App() {
  return <StoreProvider><Router /></StoreProvider>;
}

export default App;